\begin{tikzpicture}[scale=1, line cap=round, mid/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\arrow{Stealth[length=2.5mm]}}}}}]
\coordinate (B) at (0,2);
\coordinate (C) at (3.2,3.6);
\coordinate (D) at (5.6,2);
\coordinate (A) at (2.4,0.4);
\coordinate (E) at (8,0.4);
\coordinate (N) at (0.8,2.4);
\coordinate (M) at (4,1.2);
\draw (A)--(B)--(C)--(D)--cycle;
\draw (D)--(E);
\draw (N)--(D);
\draw (B)--(M);
\draw[thick,mid] (B)--(N);
\draw[thick,mid] (C)--(D);
\fill (N) circle (1.5pt);
\fill (M) circle (1.5pt);
\node[left] at (B) {$B$};
\node[above] at (C) {$C$};
\node[above right] at (D) {$D$};
\node[below] at (A) {$A$};
\node[right] at (E) {$E$};
\node[above left] at (N) {$N$};
\node[below right] at (M) {$M$};
\node at (0.25,2.55) {$\mathbf{a}$};
\node at (4.7,3.0) {$\mathbf{b}$};
\end{tikzpicture}

